                  <span hlmAvatarFallback>{{ vm.initialsFor(hero) }}</span>
                </hlm-avatar>
                <div class="heroes__names">
                  <span class="heroes__name">{{ hero.name }}</span>
                  <span class="heroes__id">{{ hero.id }} · {{ hero.alias }}</span>
                </div>
              </div>
            </td>
            <td hlmTd>
              <span hlmBadge variant="secondary">{{ hero.powerClass }}</span>
            </td>
            <td hlmTd class="heroes__power">{{ hero.powerIndex }}</td>
            <td hlmTd>
              <span hlmBadge variant="outline" class="heroes__status">
                <span
