export const POWER_CLASSES = ['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced'] as const;
export type PowerClass = (typeof POWER_CLASSES)[number];

export const HERO_STATUSES = ['Active', 'Injured', 'Reserve', 'MIA'] as const;
export type HeroStatus = (typeof HERO_STATUSES)[number];

export const CLEARANCE_TIERS = [1, 2, 3, 4, 5] as const;
export type ClearanceTier = (typeof CLEARANCE_TIERS)[number];

export interface Hero {
  readonly id: string;
  readonly name: string;
  readonly alias: string;
  readonly powerClass: PowerClass;
  /** Power index, 0-100. */
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly clearanceTier: ClearanceTier;
  readonly missionCount: number;
  /** Mission success rate as a percentage, 0-100. */
  readonly successRate: number;
}

/** A hero being recruited: the fields the recruit form collects, before the roster assigns an id and record. */
export type NewHero = Pick<Hero, 'name' | 'alias' | 'powerClass' | 'powerIndex' | 'clearanceTier'>;

import { Injectable, inject, signal } from '@angular/core';
import { form, submit, validateStandardSchema } from '@angular/forms/signals';
import { Router } from '@angular/router';
import { POWER_CLASSES, type PowerClass } from '../domain/hero.model';
import { HeroService } from '../domain/hero.service';
import { formMeta } from '../forms/zod-meta';
import { recruitSchema, type RecruitModel } from './recruit.schema';

const BLANK_RECRUIT: RecruitModel = {
  name: '',
  alias: '',
  powerClass: POWER_CLASSES[0],
  powerIndex: 0,
  clearanceTier: 1,
};

// Component-scoped (the Recruit component provides it). Owns the recruit draft and
// the act of adding it to the shared roster, then opens the new hero's dossier.
@Injectable()
export class RecruitViewModel {
  private readonly heroes = inject(HeroService);
  private readonly router = inject(Router);

  // Labels, help text and control kinds ride on the schema; the template reads them here.
  readonly meta = formMeta(recruitSchema);

  readonly classOptions: readonly { readonly value: PowerClass; readonly label: string }[] =
    POWER_CLASSES.map((value) => ({ value, label: value }));

  private readonly model = signal<RecruitModel>({ ...BLANK_RECRUIT });

  readonly form = form(this.model, (path) => validateStandardSchema(path, recruitSchema));

  setPowerClass(value: PowerClass | null | undefined): void {
    if (value) {
      this.form.powerClass().value.set(value);
    }
  }

  save(): void {
    void submit(this.form, async () => {
      const hero = this.heroes.add(this.model());
      await this.router.navigate(['/detail', hero.id]);
    });
  }
}

